var ZLEARN_QUESTION_CATALOG = [{"question":{"id":"fq1-q01","type":"recall","phase":"pretest","prompt":"ما اسم المنظومة؟ ومن ناظمها؟","answer":"«المرشد المعين على الضروري من علوم الدين»، وناظمها الشيخ العلامة عبد الواحد ابن عاشر الأنصاري الفاسي.","explain":"«المرشد المعين على الضروري من علوم الدين»، وناظمها الشيخ العلامة عبد الواحد ابن عاشر الأنصاري الفاسي.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q02","type":"recall","phase":"pretest","prompt":"ما الكتاب المعتمد في شرحها؟ ومن مؤلفه؟","answer":"«الحبل المتين»، ومؤلفه الشيخ محمد بن محمد بن عبد الله ابن المبارك، المعروف بابن المؤقت المراكشي.","explain":"«الحبل المتين»، ومؤلفه الشيخ محمد بن محمد بن عبد الله ابن المبارك، المعروف بابن المؤقت المراكشي.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q03","type":"recall","phase":"practice","prompt":"على أي بحر نُظمت المنظومة؟ وما وزنه؟","answer":"على بحر الرجز، ووزنه «مستفعلن» ست مرات.","explain":"على بحر الرجز، ووزنه «مستفعلن» ست مرات.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q04","type":"recall","phase":"practice","prompt":"كم قسمًا للمنظومة؟ وما صلتها بحديث جبريل؟","answer":"ثلاثة أقسام على ترتيب الحديث: الإيمان (العقيدة)، والإسلام (الفقه)، والإحسان (التصوف والأخلاق).","explain":"ثلاثة أقسام على ترتيب الحديث: الإيمان (العقيدة)، والإسلام (الفقه)، والإحسان (التصوف والأخلاق).","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q05","type":"recall","phase":"practice","prompt":"على أي مذهب أو طريقة بُني كل قسم؟","answer":"العقيدة على مذهب أبي الحسن الأشعري، والفقه على مذهب الإمام مالك بن أنس، والتصوف على طريقة الإمام الجنيد السالك.","explain":"العقيدة على مذهب أبي الحسن الأشعري، والفقه على مذهب الإمام مالك بن أنس، والتصوف على طريقة الإمام الجنيد السالك.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q06","type":"recall","phase":"practice","prompt":"اذكر ترتيب خطبة المنظومة.","answer":"التعريف بالنفس، البسملة، الحمدلة، الصلاة على النبي ﷺ، «وبعد»، ثم الاستعانة وبيان الغرض.","explain":"التعريف بالنفس، البسملة، الحمدلة، الصلاة على النبي ﷺ، «وبعد»، ثم الاستعانة وبيان الغرض.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q07","type":"recall","phase":"practice","prompt":"لماذا عرّف الناظم بنفسه في أول المنظومة؟","answer":"لتُعرف نسبة المنظومة إلى صاحبها، لأن هذا العلم دين فيجب النظر عمّن نأخذه، كما قال ابن سيرين.","explain":"لتُعرف نسبة المنظومة إلى صاحبها، لأن هذا العلم دين فيجب النظر عمّن نأخذه، كما قال ابن سيرين.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q08","type":"recall","phase":"practice","prompt":"ما معنى «أقطع» و«أبتر» في الحديث؟ وما حكم الصلاة على النبي ﷺ؟","answer":"معناهما: منزوع البركة. والصلاة على النبي ﷺ واجبة مرة في العمر.","explain":"معناهما: منزوع البركة. والصلاة على النبي ﷺ واجبة مرة في العمر.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q09","type":"recall","phase":"practice","prompt":"ما معنى «الأمّي» في قول الناظم؟ ولماذا نُقلت حركة الهمزة؟","answer":"هو المبتدئ: المنسوب إلى الأمة الأمية، أو إلى الأمّ أي باقٍ على حاله الأول من خلو الذهن. ونُقلت حركة الهمزة إلى الساكن الصحيح قبلها لاستقامة الوزن.","explain":"هو المبتدئ: المنسوب إلى الأمة الأمية، أو إلى الأمّ أي باقٍ على حاله الأول من خلو الذهن. ونُقلت حركة الهمزة إلى الساكن الصحيح قبلها لاستقامة الوزن.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q10","type":"recall","phase":"practice","prompt":"ما المقرر في السنة الأولى والثانية؟ وما حكم تعلم مسائله؟","answer":"قسم الفقه من المنظومة. وأحكام العبادات يجب على المسلم أن يتعلمها، ولا يُعذر بجهله إن جهل منها مسألة واحدة.","explain":"قسم الفقه من المنظومة. وأحكام العبادات يجب على المسلم أن يتعلمها، ولا يُعذر بجهله إن جهل منها مسألة واحدة.","section":"quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q12","type":"mcq","phase":"practice","prompt":"كيف ترتبط أقسام منظومة ابن عاشر الثلاثة بحديث جبريل عليه السلام؟","answer":"أن الأقسام الثلاثة جاءت على ترتيب حديث جبريل: الإيمان يقابل العقيدة، والإسلام يقابل الفقه، والإحسان يقابل التصوف.","explain":"قسّم ابن عاشر منظومته على ما جاء في حديث جبريل حين سأل النبي ﷺ عن الإيمان والإسلام والإحسان، فجاء قسم العقيدة للإيمان، وقسم الفقه للإسلام، وقسم التصوف للإحسان.","section":"parts","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q13","type":"cloze","phase":"practice","prompt":"أكمل ترتيب خطبة المنظومة كما ورد في الدرس: التعريف بالنفس، ثم البسملة، ثم الحمدلة، ثم ______، ثم «وبعد»، ثم الاستعانة وبيان الغرض.","answer":"الصلاة والسلام على النبي ﷺ","explain":"الصلاة والسلام على النبي ﷺ جاءت ثالثة بعد البسملة والحمدلة، وهي واجبة مرة في العمر.","section":"khutba","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq2-q01","type":"recall","phase":"pretest","prompt":"لماذا قدّم ابن عاشر هذه المقدمة قبل أبواب الفقه؟","answer":"ليعرّف بالمصطلحات والألفاظ التي ستتكرر في كل باب. مثال: صيام رمضان فرض، وصوم رجب وشعبان مندوب، فلا بد من معرفة معنى الفرض والمندوب.","explain":"ليعرّف بالمصطلحات والألفاظ التي ستتكرر في كل باب. مثال: صيام رمضان فرض، وصوم رجب وشعبان مندوب، فلا بد من معرفة معنى الفرض والمندوب.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q02","type":"recall","phase":"pretest","prompt":"ما أقسام الحكم الشرعي؟","answer":"خمسة: الفرض، والمندوب، والمكروه، والحرام، والمباح.","explain":"خمسة: الفرض، والمندوب، والمكروه، والحرام، والمباح.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q03","type":"recall","phase":"practice","prompt":"عرّف الفرض والمندوب.","answer":"الفرض ما طلب الشارع فعله طلبًا جازمًا. والمندوب ما طلب الشارع فعله طلبًا غير جازم.","explain":"الفرض ما طلب الشارع فعله طلبًا جازمًا. والمندوب ما طلب الشارع فعله طلبًا غير جازم.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q04","type":"recall","phase":"practice","prompt":"عرّف المكروه والحرام.","answer":"المكروه ما طلب الشارع تركه طلبًا غير جازم. والحرام ما طلب الشارع تركه طلبًا جازمًا.","explain":"المكروه ما طلب الشارع تركه طلبًا غير جازم. والحرام ما طلب الشارع تركه طلبًا جازمًا.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q05","type":"recall","phase":"practice","prompt":"ما المباح؟","answer":"ما أذن الشارع في فعله وتركه، أي تساوى فيه الفعل والترك.","explain":"ما أذن الشارع في فعله وتركه، أي تساوى فيه الفعل والترك.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q06","type":"recall","phase":"practice","prompt":"ما الذي يترتب على كل حكم من الأحكام الخمسة؟","answer":"الفرض: يُثاب فاعله ويُعاقب تاركه. المندوب: يُثاب فاعله ولا يُعاقب تاركه. الحرام: يُعاقب فاعله ويُثاب تاركه. المكروه: لا يُعاقب فاعله ويُثاب تاركه. المباح: لا ثواب ولا عقاب.","explain":"الفرض: يُثاب فاعله ويُعاقب تاركه. المندوب: يُثاب فاعله ولا يُعاقب تاركه. الحرام: يُعاقب فاعله ويُثاب تاركه. المكروه: لا يُعاقب فاعله ويُثاب تاركه. المباح: لا ثواب ولا عقاب.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q07","type":"recall","phase":"practice","prompt":"من هو الشارع؟","answer":"الله سبحانه وتعالى، وهو المشرّع. ويُقال: الرسول ﷺ نيابة عن الله أو بوحي منه.","explain":"الله سبحانه وتعالى، وهو المشرّع. ويُقال: الرسول ﷺ نيابة عن الله أو بوحي منه.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q08","type":"recall","phase":"practice","prompt":"ما أقسام الفرض؟ مثّل لكل قسم.","answer":"فرض عين: يتعين على كل مكلف بعينه، كالصلوات الخمس. وفرض كفاية: إذا قام به البعض سقط الإثم عن الباقين، كإمامة الناس في الصلاة وشهادة القاضي والأمر بالمعروف والنهي عن المنكر.","explain":"فرض عين: يتعين على كل مكلف بعينه، كالصلوات الخمس. وفرض كفاية: إذا قام به البعض سقط الإثم عن الباقين، كإمامة الناس في الصلاة وشهادة القاضي والأمر بالمعروف والنهي عن المنكر.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q09","type":"recall","phase":"practice","prompt":"ما أقسام السنة؟ مثّل لكل قسم.","answer":"سنة عينية كالوتر ونحوه، وسنة كفائية كالأذان والإقامة وغيرهما.","explain":"سنة عينية كالوتر ونحوه، وسنة كفائية كالأذان والإقامة وغيرهما.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q10","type":"recall","phase":"practice","prompt":"ما موقف ابن عاشر من المندوب والسنة؟","answer":"المالكية يفرّقون بين المندوب والسنة والرغيبة والتطوع والنافلة، لكن منهج ابن عاشر في منظومته أن المندوب يشمل السنة بقسميها.","explain":"المالكية يفرّقون بين المندوب والسنة والرغيبة والتطوع والنافلة، لكن منهج ابن عاشر في منظومته أن المندوب يشمل السنة بقسميها.","section":"l2-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q12","type":"mcq","phase":"practice","prompt":"وفقًا للدرس، ما السؤالان اللذان يُبنى عليهما تقسيم الحكم الشرعي إلى خمسة أقسام؟","answer":"هل طلب الشارع الفعل أو الترك أو أذن فيهما؟ وهل كان الطلب جازمًا أم غير جازم؟","explain":"مدار التقسيم على سؤالين: الأول ما الذي طلبه الشارع (فعل أو ترك أو إذن)، والثاني هل كان الطلب جازمًا أم غير جازم. فالطلب الجازم للفعل هو الفرض، وغير الجازم هو المندوب، والطلب الجازم للترك هو الحرام، وغير الجازم هو المكروه، والإذن في الطرفين هو المباح.","section":"l2-tree","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q13","type":"cloze","phase":"practice","prompt":"الفرض الذي يتعين على كل مكلف بعينه يسمى ______، بخلاف الفرض الذي إذا قام به البعض سقط الإثم عن الباقين ويسمى ______.","answer":"فرض عين، فرض كفاية","explain":"فرض العين يتعين على كل مكلف بعينه كالصلوات الخمس، أما فرض الكفاية فيكفي فيه البعض كإمامة الناس في الصلاة وشهادة القاضي والأمر بالمعروف والنهي عن المنكر.","section":"l2-kifaya","difficulty":3},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq3-q01","type":"recall","phase":"pretest","prompt":"ما محاور درس الطهارة؟","answer":"ثلاثة: مدخل تعريفي للمصطلحات، ثم الطهارة وأقسامها، ثم أقسام المياه وأحكامها.","explain":"ثلاثة: مدخل تعريفي للمصطلحات، ثم الطهارة وأقسامها، ثم أقسام المياه وأحكامها.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q02","type":"recall","phase":"pretest","prompt":"ما الحدث؟ وما النجاسة؟","answer":"الحدث: المنع المترتب على الأعضاء كلها أو بعضها، ويرتفع بطهارة الحدث. والنجاسة (الخبث): ما استقذره الشرع ومنع استباحة الصلاة به، وطهارتها إزالتها عن الثوب والبدن والمكان.","explain":"الحدث: المنع المترتب على الأعضاء كلها أو بعضها، ويرتفع بطهارة الحدث. والنجاسة (الخبث): ما استقذره الشرع ومنع استباحة الصلاة به، وطهارتها إزالتها عن الثوب والبدن والمكان.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q03","type":"recall","phase":"practice","prompt":"عرّف الماء المطلق. لماذا سُمّي مطلقًا؟ ولماذا سُمّي طهورًا؟","answer":"هو الماء الذي لم يتغيّر أحد أوصافه الثلاثة بما ينفك عنه غالبًا. سُمّي مطلقًا لأنه لم يُقيَّد بشيء يُنسب إليه، وسُمّي طهورًا لبلوغه الطهارة وكونه مطهِّرًا يرفع الحدث ويرفع حكم الخبث.","explain":"هو الماء الذي لم يتغيّر أحد أوصافه الثلاثة بما ينفك عنه غالبًا. سُمّي مطلقًا لأنه لم يُقيَّد بشيء يُنسب إليه، وسُمّي طهورًا لبلوغه الطهارة وكونه مطهِّرًا يرفع الحدث ويرفع حكم الخبث.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q04","type":"recall","phase":"practice","prompt":"ما الماء المضاف؟ مثّل له.","answer":"هو الماء الذي تغيّر أحد أوصافه باختلاطه بما يفارقه غالبًا، ويصح أن يُنسب إلى مغيِّره، كماء الورد وماء العجين.","explain":"هو الماء الذي تغيّر أحد أوصافه باختلاطه بما يفارقه غالبًا، ويصح أن يُنسب إلى مغيِّره، كماء الورد وماء العجين.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q05","type":"recall","phase":"practice","prompt":"ما أقسام الطهارة الشرعية؟","answer":"طهارة حدث، وتنقسم إلى صغرى وكبرى. وطهارة خبث، وتنقسم إلى طهارة الثوب وطهارة البدن وطهارة المكان.","explain":"طهارة حدث، وتنقسم إلى صغرى وكبرى. وطهارة خبث، وتنقسم إلى طهارة الثوب وطهارة البدن وطهارة المكان.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q06","type":"recall","phase":"practice","prompt":"ما أقسام الماء المتغيّر بحسب مغيِّره؟","answer":"ثلاثة: ما تغيّر بنجس فيُطرح. وما تغيّر بطاهر ينفك عنه فهو طاهر غير مطهِّر، يصلح للعادات دون العبادات. وما تغيّر بطاهر ملازم له فهو طهور مطلق.","explain":"ثلاثة: ما تغيّر بنجس فيُطرح. وما تغيّر بطاهر ينفك عنه فهو طاهر غير مطهِّر، يصلح للعادات دون العبادات. وما تغيّر بطاهر ملازم له فهو طهور مطلق.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q07","type":"recall","phase":"practice","prompt":"ما حكم الماء المتغيّر بالمغرة؟ ولماذا؟","answer":"طهور، يُستعمل في العادات والعبادات، لأن المغرة (الطين الأحمر) تلازم الماء في قراره غالبًا. فحكمه حكم الماء المطلق.","explain":"طهور، يُستعمل في العادات والعبادات، لأن المغرة (الطين الأحمر) تلازم الماء في قراره غالبًا. فحكمه حكم الماء المطلق.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q08","type":"recall","phase":"practice","prompt":"متى يُكره استعمال الماء الطهور؟","answer":"إذا كان كثيرًا وسقطت فيه نجاسة قليلة لم تغيّر أحد أوصافه، فيُكره استعماله إن وُجد غيره.","explain":"إذا كان كثيرًا وسقطت فيه نجاسة قليلة لم تغيّر أحد أوصافه، فيُكره استعماله إن وُجد غيره.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q09","type":"recall","phase":"practice","prompt":"ما معنى «فصل»؟ وما أصل كلمة «بما» في البيت؟","answer":"الفصل هو الحاجز بين الشيئين، وهنا بين المقدمات وقسم الفقه. وأصل «بما» هو «بماء»، حُذفت همزته للتخفيف ولمناسبة الوزن.","explain":"الفصل هو الحاجز بين الشيئين، وهنا بين المقدمات وقسم الفقه. وأصل «بما» هو «بماء»، حُذفت همزته للتخفيف ولمناسبة الوزن.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q10","type":"recall","phase":"practice","prompt":"ما الفائدة التي ختم بها الأستاذ؟","answer":"حديث الرجل الذي سأل النبي ﷺ عن الوضوء بماء البحر، فقال: «هو الطهور ماؤه الحل ميتته». وفيه أن ماء البحر طهور.","explain":"حديث الرجل الذي سأل النبي ﷺ عن الوضوء بماء البحر، فقال: «هو الطهور ماؤه الحل ميتته». وفيه أن ماء البحر طهور.","section":"l3-quiz","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q12","type":"mcq","phase":"practice","prompt":"وفقًا للدرس، ما الذي يحدد حكم الماء المتغير؟","answer":"ما تغيّر به: فإن تغيّر بطاهر ملازم له فهو طهور، أو بطاهر ينفك عنه فهو طاهر غير مطهِّر، أو بنجس فيُطرح.","explain":"مدار أحكام المياه على سؤالين: هل تغيّر أحد أوصاف الماء (اللون أو الطعم أو الريح)؟ وبماذا تغيّر؟ فإن بقي على أصله أو تغيّر بطاهر ملازم له فهو طهور، وإن تغيّر بطاهر ينفك عنه فللعادات دون العبادات، وإن تغيّر بنجس فيُطرح.","section":"l3-water","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q13","type":"cloze","phase":"practice","prompt":"إذا تغيّر الماء بطاهر ينفك عنه كالصابون أو الزيت أو اللبن، فيصلح ______ دون ______.","answer":"للعادات، العبادات","explain":"الماء المتغير بطاهر ينفك عنه عادةً هو طاهر غير مطهِّر: يصلح للعادات كالطبخ والسقي، ولا يصلح للعبادات كالوضوء والغسل.","section":"l3-water","difficulty":3},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"aq1-q01","type":"recall","phase":"pretest","prompt":"ما الكتاب المعتمد في مادة العقيدة؟ وما المنظومة التي يشرحها؟","answer":"«الشذرات الذهبية في شرح المنظومة الشرنوبية» للإمام إبراهيم بن أحمد المارغني الزيتوني. والمنظومة الشرنوبية لأبي محمد عبد المجيد الشرنوبي الأزهري.","explain":"«الشذرات الذهبية في شرح المنظومة الشرنوبية» للإمام إبراهيم بن أحمد المارغني الزيتوني. والمنظومة الشرنوبية لأبي محمد عبد المجيد الشرنوبي الأزهري.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q02","type":"recall","phase":"pretest","prompt":"ماذا يدل عليه كون الشارح زيتونيًا والناظم أزهريًا؟","answer":"يدل على التلاقي والتلاقح بين جامع الزيتونة والجامع الأزهر.","explain":"يدل على التلاقي والتلاقح بين جامع الزيتونة والجامع الأزهر.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q03","type":"recall","phase":"practice","prompt":"لماذا يُعد علم العقيدة أهم علوم الإسلام؟","answer":"لأنه متعلق بالله تبارك وتعالى، وأعظم ما يتقرب به العبد إلى ربه معرفة توحيده.","explain":"لأنه متعلق بالله تبارك وتعالى، وأعظم ما يتقرب به العبد إلى ربه معرفة توحيده.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q04","type":"recall","phase":"practice","prompt":"ما الذي تتضمنه معرفة التوحيد؟","answer":"العلم بأسماء الله وصفاته وأفعاله، أي ما يجب له تعالى وما يستحيل في حقه وما يجوز.","explain":"العلم بأسماء الله وصفاته وأفعاله، أي ما يجب له تعالى وما يستحيل في حقه وما يجوز.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q05","type":"recall","phase":"practice","prompt":"ما ثمرة هذا العلم؟","answer":"أن يعبد العبد ربه عبادة يستحق بها الثواب، ويسعد بها في الدنيا وفي الآخرة.","explain":"أن يعبد العبد ربه عبادة يستحق بها الثواب، ويسعد بها في الدنيا وفي الآخرة.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q06","type":"recall","phase":"practice","prompt":"ما المباحث الثلاثة التي تدور عليها مسائل العقيدة؟","answer":"الإلهيات، والنبوات، والسمعيات.","explain":"الإلهيات، والنبوات، والسمعيات.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q07","type":"recall","phase":"practice","prompt":"ما موضوع مبحث الإلهيات؟ وما موضوع مبحث النبوات؟","answer":"الإلهيات: ذات الله تبارك وتعالى، من حيث ما يجب له وما يستحيل عليه وما يجوز في حقه. والنبوات: ذات الأنبياء والمرسلين عليهم الصلاة والسلام، من حيث ما يجب لهم وما يستحيل عليهم وما يجوز في حقهم.","explain":"الإلهيات: ذات الله تبارك وتعالى، من حيث ما يجب له وما يستحيل عليه وما يجوز في حقه. والنبوات: ذات الأنبياء والمرسلين عليهم الصلاة والسلام، من حيث ما يجب لهم وما يستحيل عليهم وما يجوز في حقهم.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q08","type":"recall","phase":"practice","prompt":"ما السمعيات؟","answer":"المسائل التي أخبر بها الصادق المصدوق ﷺ، وما ثبت بالقرآن الكريم. والعقل يصدّقها ولا يحيلها.","explain":"المسائل التي أخبر بها الصادق المصدوق ﷺ، وما ثبت بالقرآن الكريم. والعقل يصدّقها ولا يحيلها.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q09","type":"recall","phase":"practice","prompt":"ما مقرر السداسي الأول؟ وما الصفات التي سيُتحدث عنها؟","answer":"مبحث الإلهيات، وخاصة ما يجب لله تبارك وتعالى. ويتناول الصفة النفسية (الوجود)، والصفات السلبية، وصفات المعاني، والصفات المعنوية.","explain":"مبحث الإلهيات، وخاصة ما يجب لله تبارك وتعالى. ويتناول الصفة النفسية (الوجود)، والصفات السلبية، وصفات المعاني، والصفات المعنوية.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q10","type":"recall","phase":"practice","prompt":"ما مقرر السداسي الثاني؟","answer":"مبحث النبوات، ثم مبحث السمعيات.","explain":"مبحث النبوات، ثم مبحث السمعيات.","section":"aq1-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q12","type":"mcq","phase":"practice","prompt":"أيّ العبارات التالية تصف المباحث الثلاثة التي تدور عليها مسائل العقيدة وصفًا صحيحًا؟\nأ) الإلهيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه. النبوات: ما يجب للأنبياء والمرسلين وما يستحيل عليهم وما يجوز في حقهم. السمعيات: ما أخبر به الصادق المصدوق ﷺ وما ثبت بالقرآن الكريم.\nب) الإلهيات: ما أخبر به الصادق المصدوق ﷺ. النبوات: ذات الله تبارك وتعالى. السمعيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه.\nج) الإلهيات: ما يجب للأنبياء والمرسلين. النبوات: ما ثبت بالقرآن الكريم. السمعيات: ذات الله تبارك وتعالى.\nد) الإلهيات: ما ثبت بالقرآن الكريم. النبوات: ما أخبر به الصادق المصدوق ﷺ. السمعيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه.","answer":"الإلهيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه. النبوات: ما يجب للأنبياء والمرسلين وما يستحيل عليهم وما يجوز في حقهم. السمعيات: ما أخبر به الصادق المصدوق ﷺ وما ثبت بالقرآن الكريم.","explain":"تدور مسائل العقيدة على ثلاثة مباحث: الإلهيات وهي المسائل المتعلقة بذات الله تبارك وتعالى من حيث ما يجب له وما يستحيل عليه وما يجوز في حقه، والنبوات وهي المسائل المتعلقة بذات الأنبياء والمرسلين عليهم الصلاة والسلام من حيث ما يجب لهم وما يستحيل عليهم وما يجوز في حقهم، والسمعيات وهي ما أخبر به الصادق المصدوق ﷺ وما ثبت بالقرآن الكريم.","section":"aq1-parts","difficulty":2},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q13","type":"cloze","phase":"practice","prompt":"أكمل الفراغين: إذا كان الطالب يدرس المسائل المتعلقة بذات الله تبارك وتعالى من حيث ما يجب له وما يستحيل عليه وما يجوز في حقه، فهو يدرس مبحث الـ……، وهذا المبحث يُدرَّس في السداسي الـ…… من السنة.","answer":"الإلهيات؛ الأول","explain":"مبحث الإلهيات هو المسائل المتعلقة بذات الله تبارك وتعالى من حيث ما يجب له وما يستحيل عليه وما يجوز في حقه، ومقرر السداسي الأول هو مبحث الإلهيات، ثم السداسي الثاني للنبوات فالسمعيات.","section":"aq1-parts","difficulty":3},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq2-q01","type":"recall","phase":"pretest","prompt":"ما المبادئ العشرة؟ ومن نظمها؟","answer":"الحد، والموضوع، والثمرة، والفضل، والنسبة، والواضع، والاسم، والاستمداد، وحكم الشارع، والمسائل. نظمها الإمام الصبّان في ثلاثة أبيات.","explain":"الحد، والموضوع، والثمرة، والفضل، والنسبة، والواضع، والاسم، والاستمداد، وحكم الشارع، والمسائل. نظمها الإمام الصبّان في ثلاثة أبيات.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q02","type":"recall","phase":"pretest","prompt":"عرّف علم العقيدة.","answer":"العلم بالقواعد الشرعية الاعتقادية المكتسب من أدلتها اليقينية.","explain":"العلم بالقواعد الشرعية الاعتقادية المكتسب من أدلتها اليقينية.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q03","type":"recall","phase":"practice","prompt":"ماذا يخرج بقولنا «الشرعية» و«الاعتقادية» و«المكتسب من أدلتها اليقينية»؟","answer":"«الشرعية» يخرج بها القواعد غير الشرعية. و«الاعتقادية» يخرج بها القواعد الفرعية والأصولية. و«من أدلتها اليقينية» يخرج بها المسائل الفروعية، لأن أدلتها ظنية وقد تكون قطعية.","explain":"«الشرعية» يخرج بها القواعد غير الشرعية. و«الاعتقادية» يخرج بها القواعد الفرعية والأصولية. و«من أدلتها اليقينية» يخرج بها المسائل الفروعية، لأن أدلتها ظنية وقد تكون قطعية.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q04","type":"recall","phase":"practice","prompt":"لماذا سُميت العقيدة بهذا الاسم؟","answer":"لأنها ما يجزم به المسلم جزمًا ثابتًا لا يقبل الشك والريب. وهي من عقد الحبل إذا ربطه وشدّه.","explain":"لأنها ما يجزم به المسلم جزمًا ثابتًا لا يقبل الشك والريب. وهي من عقد الحبل إذا ربطه وشدّه.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q05","type":"recall","phase":"practice","prompt":"ما الفرق بين أصول الدين وأصول الفقه؟","answer":"أصول الدين هو علم العقيدة. وأصول الفقه هو أدلة الفقه، وكيفية الاستفادة منها، وحال المستفيد.","explain":"أصول الدين هو علم العقيدة. وأصول الفقه هو أدلة الفقه، وكيفية الاستفادة منها، وحال المستفيد.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q06","type":"recall","phase":"practice","prompt":"ما موضوع علم العقيدة؟ ولماذا تناول ذات الأنبياء؟","answer":"ذات الله تعالى، من حيث ما يجب له من صفات الكمال وما يستحيل في حقه من صفات النقص وما يجوز عليه. وتناول ذات الأنبياء لأن الواصل بيننا وبين الله هم الرسل.","explain":"ذات الله تعالى، من حيث ما يجب له من صفات الكمال وما يستحيل في حقه من صفات النقص وما يجوز عليه. وتناول ذات الأنبياء لأن الواصل بيننا وبين الله هم الرسل.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q07","type":"recall","phase":"practice","prompt":"ما موضوع الفقه؟ وما موضوع أصول الفقه؟ وما موضوع النحو؟","answer":"الفقه: فعل المكلف من حيث ما يجوز له وما يحل له وما يحرم. وأصول الفقه: الأدلة الإجمالية من حيث ما يعرض لها. والنحو: الكلمة العربية من حيث الإعراب والبناء.","explain":"الفقه: فعل المكلف من حيث ما يجوز له وما يحل له وما يحرم. وأصول الفقه: الأدلة الإجمالية من حيث ما يعرض لها. والنحو: الكلمة العربية من حيث الإعراب والبناء.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q08","type":"recall","phase":"practice","prompt":"ما ثمرة علم العقيدة؟","answer":"تربية الإيمان بالله، وتعزيز الثقة به، وتخليص المسلم من الشبهات والاعتقادات الباطلة، وتحصيل السعادتين في الدنيا وفي الآخرة، والنجاة من ربقة التقليد إلى التبصر والاعتقاد الصحيح.","explain":"تربية الإيمان بالله، وتعزيز الثقة به، وتخليص المسلم من الشبهات والاعتقادات الباطلة، وتحصيل السعادتين في الدنيا وفي الآخرة، والنجاة من ربقة التقليد إلى التبصر والاعتقاد الصحيح.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q09","type":"recall","phase":"practice","prompt":"بماذا يُقاس شرف العلم؟ وما الذي اجتمع في العقيدة؟","answer":"يُقاس بشرف المعلوم، والموضوع، والغاية، والدليل. وقد اجتمعت كلها في علم العقيدة.","explain":"يُقاس بشرف المعلوم، والموضوع، والغاية، والدليل. وقد اجتمعت كلها في علم العقيدة.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q10","type":"recall","phase":"practice","prompt":"من واضع علم العقيدة؟ وهل يعني اختلافهم أن عقيدتهم مختلفة؟","answer":"أئمة أهل السنة والجماعة: أحمد بن حنبل، وأبو الحسن الأشعري، وأبو منصور الماتريدي ونظراؤهم. ولا، فهم متفقون على أصول العقائد، واختلفوا في مسائل فرعية منها.","explain":"أئمة أهل السنة والجماعة: أحمد بن حنبل، وأبو الحسن الأشعري، وأبو منصور الماتريدي ونظراؤهم. ولا، فهم متفقون على أصول العقائد، واختلفوا في مسائل فرعية منها.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q11","type":"recall","phase":"practice","prompt":"ما أسماء هذا العلم؟ ولماذا سُمّي «الفقه الأكبر»؟","answer":"علم العقيدة، وعلم التوحيد، وعلم أصول الدين، وعلم الفقه الأكبر. سمّاه به الإمام أبو حنيفة في مقابل الفقه الأصغر (علم الفروع)، لأنه يهتم بأكبر مسائل الإسلام وأهمها.","explain":"علم العقيدة، وعلم التوحيد، وعلم أصول الدين، وعلم الفقه الأكبر. سمّاه به الإمام أبو حنيفة في مقابل الفقه الأصغر (علم الفروع)، لأنه يهتم بأكبر مسائل الإسلام وأهمها.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q12","type":"recall","phase":"practice","prompt":"من أين استمد هذا العلم؟ وما حكم تعلمه؟","answer":"استمد من القرآن الكريم، والسنة النبوية، وإجماع السلف، والبراهين العقلية القطعية. وحكم تعلمه: واجب عيني فيما لا يصح الإيمان إلا به، وواجب كفائي فيما زاد على ذلك من التفصيل وإقامة الأدلة ودحض الشبه.","explain":"استمد من القرآن الكريم، والسنة النبوية، وإجماع السلف، والبراهين العقلية القطعية. وحكم تعلمه: واجب عيني فيما لا يصح الإيمان إلا به، وواجب كفائي فيما زاد على ذلك من التفصيل وإقامة الأدلة ودحض الشبه.","section":"aq2-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq3-q01","type":"recall","phase":"pretest","prompt":"لماذا نبدأ قراءة الكتاب بترجمة مؤلفه وناظمه؟","answer":"لأن الإسناد من الدين، ولا يجوز أخذ العلم من الكتب المجهولة. ولولا الإسناد لقال من شاء ما شاء.","explain":"لأن الإسناد من الدين، ولا يجوز أخذ العلم من الكتب المجهولة. ولولا الإسناد لقال من شاء ما شاء.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q02","type":"recall","phase":"pretest","prompt":"هل تكفي معرفة المؤلف لاعتماد كتابه؟","answer":"لا. قد يكون المؤلف معروفًا لكنه لا يسير على المقررات المعتمدة، فيُترك قوله. والمقررات المعتمدة هي ما عليه أئمة الزيتونة والأزهر من طريقة أهل السنة والجماعة.","explain":"لا. قد يكون المؤلف معروفًا لكنه لا يسير على المقررات المعتمدة، فيُترك قوله. والمقررات المعتمدة هي ما عليه أئمة الزيتونة والأزهر من طريقة أهل السنة والجماعة.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q03","type":"recall","phase":"practice","prompt":"من شارح الكتاب؟ ومتى وُلد وتوفي؟","answer":"الإمام إبراهيم بن أحمد المارغني الزيتوني التونسي الفقيه المالكي. وُلد بتونس سنة 1865م، وتوفي سنة 1931م، ودُفن بالجلاز.","explain":"الإمام إبراهيم بن أحمد المارغني الزيتوني التونسي الفقيه المالكي. وُلد بتونس سنة 1865م، وتوفي سنة 1931م، ودُفن بالجلاز.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q04","type":"recall","phase":"practice","prompt":"اذكر ثلاثة من شيوخه وثلاثة من تلاميذه.","answer":"من شيوخه: عمر بن الشيخ، وسالم بوحاجب، ومحمود بن الخوجة. ومن تلاميذه: محمد الطاهر بن عاشور، ومحمد الخضر حسين، وبشير النيفر.","explain":"من شيوخه: عمر بن الشيخ، وسالم بوحاجب، ومحمود بن الخوجة. ومن تلاميذه: محمد الطاهر بن عاشور، ومحمد الخضر حسين، وبشير النيفر.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q05","type":"recall","phase":"practice","prompt":"ما كتبه الثلاثة في العقيدة؟ ولأي مستوى كل كتاب؟","answer":"الشذرات الذهبية للمبتدئين، وطالع البشرى على العقيدة الصغرى للمتوسطين، وبغية المريد بشرح جوهرة التوحيد للمستوى الأعلى.","explain":"الشذرات الذهبية للمبتدئين، وطالع البشرى على العقيدة الصغرى للمتوسطين، وبغية المريد بشرح جوهرة التوحيد للمستوى الأعلى.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q06","type":"recall","phase":"practice","prompt":"من ناظم المنظومة؟ وإلى ماذا ينسب؟","answer":"الإمام أبو محمد عبد المجيد الشرنوبي الأزهري. «الشرنوبي» نسبة إلى قرية الشرنوب في مصر، و«الأزهري» نسبة إلى الجامع الأزهر، وكان من مشايخه.","explain":"الإمام أبو محمد عبد المجيد الشرنوبي الأزهري. «الشرنوبي» نسبة إلى قرية الشرنوب في مصر، و«الأزهري» نسبة إلى الجامع الأزهر، وكان من مشايخه.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q07","type":"recall","phase":"practice","prompt":"كم بيتًا في المنظومة؟ وعلى أي بحر؟ وماذا تضمنت؟","answer":"29 بيتًا من بحر الرجز. وتضمنت من عقائد أهل السنة المحررات، ما يكفي المبتدئ في الإلهيات والنبوات والسمعيات.","explain":"29 بيتًا من بحر الرجز. وتضمنت من عقائد أهل السنة المحررات، ما يكفي المبتدئ في الإلهيات والنبوات والسمعيات.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q08","type":"recall","phase":"practice","prompt":"ما الفرق بين النظم والنثر؟ ولماذا يفيد النظم الطلبة؟","answer":"النظم كلام عربي منظوم على وزن، والنثر كلام عربي منثور. وكلاهما يصلح للتعليم. والنظم مفيد لأنه مختصر ويحتوي على مسائل كثيرة يسهل استحضارها.","explain":"النظم كلام عربي منظوم على وزن، والنثر كلام عربي منثور. وكلاهما يصلح للتعليم. والنظم مفيد لأنه مختصر ويحتوي على مسائل كثيرة يسهل استحضارها.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q09","type":"recall","phase":"practice","prompt":"ما سبب تأليف الشرح؟ وما معنى «شرح ممزوج»؟","answer":"سأله بعض المبتدئين الحافظين للمنظومة أن يشرحها ليفهموا معانيها. والممزوج هو الذي يخلط النظم بالشرح، بخلاف طريقة التعليق: «قال الناظم فهو كذا».","explain":"سأله بعض المبتدئين الحافظين للمنظومة أن يشرحها ليفهموا معانيها. والممزوج هو الذي يخلط النظم بالشرح، بخلاف طريقة التعليق: «قال الناظم فهو كذا».","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q10","type":"recall","phase":"practice","prompt":"ما حكم الدليل الإجمالي في العقائد؟","answer":"يكفي في الخروج من التقليد. فالواجب تحصيل ما يصح به الاعتقاد بدليل ولو إجمالي. ومن قصّر فيه فهو آثم، ويصح إيمانه على الصحيح من أقوال أهل العلم.","explain":"يكفي في الخروج من التقليد. فالواجب تحصيل ما يصح به الاعتقاد بدليل ولو إجمالي. ومن قصّر فيه فهو آثم، ويصح إيمانه على الصحيح من أقوال أهل العلم.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q11","type":"recall","phase":"practice","prompt":"لماذا سُمّي الكتاب «الشذرات الذهبية»؟","answer":"الشذرة هي القطعة من الذهب، فكأنه حلّى الكتاب بالذهب.","explain":"الشذرة هي القطعة من الذهب، فكأنه حلّى الكتاب بالذهب.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q12","type":"recall","phase":"practice","prompt":"ما حكم التوسل بجاه النبي ﷺ عند الأستاذ؟ وما دليله؟","answer":"مندوب ولا حرج فيه، ولا خلاف فيه بين المذاهب الأربعة. ودليله إرشاد النبي ﷺ الرجل الأعمى أن يتوجه إلى الله بالدعاء ويسأله بحق نبيه. والنافع والضار هو الله.","explain":"مندوب ولا حرج فيه، ولا خلاف فيه بين المذاهب الأربعة. ودليله إرشاد النبي ﷺ الرجل الأعمى أن يتوجه إلى الله بالدعاء ويسأله بحق نبيه. والنافع والضار هو الله.","section":"aq3-quiz","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"tj1-q01","type":"recall","phase":"pretest","prompt":"كيف كان علم التجويد يُذكر في القديم؟ ولماذا أُفرد؟","answer":"كان مندمجًا مع كتب النحو والصرف، يذكره أكثر علمائها في آخر الأبحاث. وأُفرد في كتب مستقلة لما وجد العلماء ضعفًا في تلاوة المسلمين لكتاب الله.","explain":"كان مندمجًا مع كتب النحو والصرف، يذكره أكثر علمائها في آخر الأبحاث. وأُفرد في كتب مستقلة لما وجد العلماء ضعفًا في تلاوة المسلمين لكتاب الله.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q02","type":"recall","phase":"pretest","prompt":"على من يجب تعلم التجويد؟","answer":"على كل مسلم عاقل بالغ إذا أراد أن يقرأ القرآن، فيتعلم قبل القراءة مخارج الحروف وصفاتها.","explain":"على كل مسلم عاقل بالغ إذا أراد أن يقرأ القرآن، فيتعلم قبل القراءة مخارج الحروف وصفاتها.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q03","type":"recall","phase":"practice","prompt":"ما فائدة المبادئ العشرة؟","answer":"يمرّ بها طالب العلم مرورًا ليفهم موضوع العلم الذي سيقدم على دراسته وحفظه. وهي لكل علم من علوم الشرع وعلوم الآلة.","explain":"يمرّ بها طالب العلم مرورًا ليفهم موضوع العلم الذي سيقدم على دراسته وحفظه. وهي لكل علم من علوم الشرع وعلوم الآلة.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q04","type":"recall","phase":"practice","prompt":"عدّد المبادئ العشرة.","answer":"الحد، الموضوع، الثمرة، الفضل، النسبة، الواضع، الاسم، الاستمداد، حكم الشارع، المسائل.","explain":"الحد، الموضوع، الثمرة، الفضل، النسبة، الواضع، الاسم، الاستمداد، حكم الشارع، المسائل.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q05","type":"recall","phase":"practice","prompt":"ما معنى التجويد لغةً واصطلاحًا؟","answer":"لغةً: التحسين. اصطلاحًا: علم يبحث عن مخارج الحروف وصفاتها، ويُطلق أيضًا على إعطاء الحروف حقوقها من المخارج والصفات.","explain":"لغةً: التحسين. اصطلاحًا: علم يبحث عن مخارج الحروف وصفاتها، ويُطلق أيضًا على إعطاء الحروف حقوقها من المخارج والصفات.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q06","type":"recall","phase":"practice","prompt":"ما الفرق بين المخرج والصفة؟","answer":"لكل حرف مخرج واحد، وله صفات عدة. فالمخارج جمع مخرج، وهو موضع خروج الحرف.","explain":"لكل حرف مخرج واحد، وله صفات عدة. فالمخارج جمع مخرج، وهو موضع خروج الحرف.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q07","type":"recall","phase":"practice","prompt":"اذكر صفات حرف الصاد وعرّف كل صفة.","answer":"الهمس: جريان النفس. الصفير: حدّة في الصوت. الرخاوة: جريان الصوت. الاستعلاء: تفخيم الحرف وتسمينه. الإطباق: انطباق طائفة عظمى من اللسان على الحنك الأعلى.","explain":"الهمس: جريان النفس. الصفير: حدّة في الصوت. الرخاوة: جريان الصوت. الاستعلاء: تفخيم الحرف وتسمينه. الإطباق: انطباق طائفة عظمى من اللسان على الحنك الأعلى.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q08","type":"recall","phase":"practice","prompt":"ما حروف الإطباق؟","answer":"أربعة: الصاد والضاد والطاء والظاء.","explain":"أربعة: الصاد والضاد والطاء والظاء.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q09","type":"recall","phase":"practice","prompt":"هل كل حرف مستعلٍ مطبق؟ وضّح بمثال.","answer":"لا. كل مطبق مستعلٍ، وليس كل مستعلٍ مطبقًا. فالقاف مستعلية وليست مطبقة.","explain":"لا. كل مطبق مستعلٍ، وليس كل مستعلٍ مطبقًا. فالقاف مستعلية وليست مطبقة.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q10","type":"recall","phase":"practice","prompt":"ما الفرق بين الحركة الأصلية والحركة العارضة؟","answer":"الأصلية ذاتية للحرف. والعارضة نستعيرها للتوصل بالنطق إلى الحرف الذي يليها، وليست أصلية.","explain":"الأصلية ذاتية للحرف. والعارضة نستعيرها للتوصل بالنطق إلى الحرف الذي يليها، وليست أصلية.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q11","type":"recall","phase":"practice","prompt":"لماذا تُكسر النون في «لمن ارتضى»؟","answer":"لأن النون الساكنة يلقاها ساكن بعدها، ويستحيل النطق بحرفين ساكنين معًا. فيُحذف سكون الأول ويؤتى بكسرة عارضة للتوصل إلى الحرف الذي يليه.","explain":"لأن النون الساكنة يلقاها ساكن بعدها، ويستحيل النطق بحرفين ساكنين معًا. فيُحذف سكون الأول ويؤتى بكسرة عارضة للتوصل إلى الحرف الذي يليه.","section":"tj1-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q13","type":"mcq","phase":"practice","prompt":"ما العلاقة الصحيحة بين الاستعلاء والإطباق كما وردت في الدرس؟","answer":"كل مطبق مستعلٍ، وليس كل مستعلٍ مطبقًا. فالقاف مستعلية وليست مطبقة، أما الصاد والضاد والطاء والظاء فهي مستعلية ومطبقة معًا.","explain":"وضّح الدرس أن حروف الإطباق الأربعة (ص ض ط ظ) كلها مستعلية، لكن ليست كل مستعلٍ مطبقًا لأن القاف مستعلية دون إطباق.","section":"tj1-itbaq","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj2-q01","type":"recall","phase":"pretest","prompt":"ما موضوع علم التجويد؟","answer":"الكلمة القرآنية من حيث هي، أي من حيث مخارج حروفها وصفاتها حيثما وقعت في كتاب الله، وما يتكون منه العلم كالمدود والإخفاء والإدغام.","explain":"الكلمة القرآنية من حيث هي، أي من حيث مخارج حروفها وصفاتها حيثما وقعت في كتاب الله، وما يتكون منه العلم كالمدود والإخفاء والإدغام.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q02","type":"recall","phase":"pretest","prompt":"إلى أي علم ينتسب التجويد؟","answer":"هو من العلوم العربية، وداخل في علم التصريف، ولذلك يُذكر في آخر بعض كتب الصرف كالشافية.","explain":"هو من العلوم العربية، وداخل في علم التصريف، ولذلك يُذكر في آخر بعض كتب الصرف كالشافية.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q03","type":"recall","phase":"practice","prompt":"ما ثمرة علم التجويد؟","answer":"حفظ اللسان من اللحن في قراءة القرآن، ليقرأ قراءة صحيحة سليمة فينال رضا الله وتتحقق له سعادة الدارين.","explain":"حفظ اللسان من اللحن في قراءة القرآن، ليقرأ قراءة صحيحة سليمة فينال رضا الله وتتحقق له سعادة الدارين.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q04","type":"recall","phase":"practice","prompt":"من أين يستمد التجويد فضله؟","answer":"من شرف موضوعه، وهو كلام الله عز وجل القديم الذي لا يُمَلّ سماعه. وهو علم شرعي.","explain":"من شرف موضوعه، وهو كلام الله عز وجل القديم الذي لا يُمَلّ سماعه. وهو علم شرعي.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q05","type":"recall","phase":"practice","prompt":"هل وضع النبي ﷺ قواعد التجويد؟ ومن واضعه نظريًا؟","answer":"لا، وإنما علّم القراءة بالتلقي والمشافهة. وقيل: واضعه الخليل بن أحمد الفراهيدي، وقيل: أبو الأسود الدؤلي، وقيل: حفص بن عمر الدوري، وقيل: أئمة القراء.","explain":"لا، وإنما علّم القراءة بالتلقي والمشافهة. وقيل: واضعه الخليل بن أحمد الفراهيدي، وقيل: أبو الأسود الدؤلي، وقيل: حفص بن عمر الدوري، وقيل: أئمة القراء.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q06","type":"recall","phase":"practice","prompt":"من أين استمد التجويد؟ وكيف وصل إلينا؟","answer":"من كيفية قراءة النبي ﷺ عن جبريل عن اللوح المحفوظ. نقله الصحابة بالمشافهة، ثم التابعون، ثم أئمة القراءة والمشايخ بسند متصل دون انقطاع.","explain":"من كيفية قراءة النبي ﷺ عن جبريل عن اللوح المحفوظ. نقله الصحابة بالمشافهة، ثم التابعون، ثم أئمة القراءة والمشايخ بسند متصل دون انقطاع.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q07","type":"recall","phase":"practice","prompt":"ما حكم تعلم التجويد؟","answer":"فرض كفاية: إذا تعلمه بعض أهل القرية سقط الإثم عن الباقين، وإن خلت منه أثم أهلها كلهم. وهو فرض عين على من أراد أن يقرأ القرآن.","explain":"فرض كفاية: إذا تعلمه بعض أهل القرية سقط الإثم عن الباقين، وإن خلت منه أثم أهلها كلهم. وهو فرض عين على من أراد أن يقرأ القرآن.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q08","type":"recall","phase":"practice","prompt":"ما أدلة وجوب التجويد؟","answer":"الكتاب: «ورتل القرآن ترتيلا». والسنة: حديث «رب قارئ للقرآن والقرآن يلعنه»، وحديث حذيفة «اقرؤوا القرآن بلحون العرب». والإجماع: أجمعت الأمة على وجوبه ولم يخالف أحد.","explain":"الكتاب: «ورتل القرآن ترتيلا». والسنة: حديث «رب قارئ للقرآن والقرآن يلعنه»، وحديث حذيفة «اقرؤوا القرآن بلحون العرب». والإجماع: أجمعت الأمة على وجوبه ولم يخالف أحد.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q09","type":"recall","phase":"practice","prompt":"ماذا قال علي رضي الله عنه في معنى الترتيل؟ وماذا يُفهم منه؟","answer":"قال: الترتيل هو تجويد الحروف ومعرفة الوقوف. فمن تعلم تجويد الحروف دون معرفة الوقوف لا يُؤتمن على علمه ولا يُؤخذ منه.","explain":"قال: الترتيل هو تجويد الحروف ومعرفة الوقوف. فمن تعلم تجويد الحروف دون معرفة الوقوف لا يُؤتمن على علمه ولا يُؤخذ منه.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q10","type":"recall","phase":"practice","prompt":"عرّف بمتن تحفة الأطفال.","answer":"متن للشيخ الجمزوري، تلقته الأمة بالقبول، جمع أهم مباحث التجويد ليسهل على المبتدئين تعلمها وحفظها. وأفضل شروحه شرح ناظمه، اقتصر فيه على ما لا بد منه.","explain":"متن للشيخ الجمزوري، تلقته الأمة بالقبول، جمع أهم مباحث التجويد ليسهل على المبتدئين تعلمها وحفظها. وأفضل شروحه شرح ناظمه، اقتصر فيه على ما لا بد منه.","section":"tj2-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q12","type":"mcq","phase":"practice","prompt":"ما الحكمة من كون تعلم التجويد فرض كفاية على الأمة وفرض عين على من أراد قراءة القرآن؟","answer":"قراءة القرآن واجبة على من أرادها، فوجب عليه أن يتعلم مخارج الحروف وصفاتها ليصح أداءه. فإذا تعلمه بعض أهل القرية سقط الإثم عن الباقين، وإن خلت القرية من عالم به أثم أهلها كلهم.","explain":"فرض العين لأن كل من أراد القراءة يحتاج إلى التجويد لتصح تلاوته. وفرض الكفاية لأن علم التجويد يجب أن يكون موجودًا في كل  Muslim community لتستقيم قراءة أهلها.","section":"tj2-hukm","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q13","type":"cloze","phase":"practice","prompt":"إذا تعلم التجويد بعض أهل القرية، فإن الإثم يسقط عن __________؛ أما إذا خلت القرية من عالم به فإن __________ أهلها.","answer":"الباقين، يأثم","explain":"هذا هو معنى فرض الكفاية: إذا قام به البعض سقط الإثم عن الباقين، وإذا لم يقم به أحد أثم الجميع. أما فرض العين فيتعلق بمن أراد قراءة القرآن.","section":"tj2-hukm","difficulty":3},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj3-q01","type":"recall","phase":"pretest","prompt":"من هو ناظم تحفة الأطفال؟","answer":"سليمان ابن حسين بن محمد الجمزوري","explain":"سليمان ابن حسين بن محمد الجمزوري","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q02","type":"recall","phase":"pretest","prompt":"ما اسم الشرح الذي وضعه الناظم على نظمه؟","answer":"فتح الأقفال بشرح تحفة الأطفال","explain":"فتح الأقفال بشرح تحفة الأطفال","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q03","type":"recall","phase":"practice","prompt":"على من اعتمد الناظم في أصل شرحه؟","answer":"شرح ولد شيخنا الشيخ محمد الميهي","explain":"شرح ولد شيخنا الشيخ محمد الميهي","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q04","type":"recall","phase":"practice","prompt":"من هو الذي نقل عنه الناظم؟","answer":"شيخنا نور الدين علي بن عمر بن حمد بن عمر بن ناجي بن قنيش (أو فنيش) الميهي","explain":"شيخنا نور الدين علي بن عمر بن حمد بن عمر بن ناجي بن قنيش (أو فنيش) الميهي","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q05","type":"recall","phase":"practice","prompt":"ما معنى الحمد؟","answer":"الثناء الحسن الثابت بالاختصاص لله تعالى، باللسان على الوصف الجميل من نعمه أو غيرها","explain":"الثناء الحسن الثابت بالاختصاص لله تعالى، باللسان على الوصف الجميل من نعمه أو غيرها","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q06","type":"recall","phase":"practice","prompt":"ما معنى الصلاة على النبي ﷺ؟","answer":"طلب من الله أن ينزل رحمته المقرونة بالتعظيم على سيدنا محمد","explain":"طلب من الله أن ينزل رحمته المقرونة بالتعظيم على سيدنا محمد","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q07","type":"recall","phase":"practice","prompt":"ما معنى القبول؟","answer":"ترتيب الغرض المطلوب للداعي على دعائه، كترتيب الثواب على الطاعة","explain":"ترتيب الغرض المطلوب للداعي على دعائه، كترتيب الثواب على الطاعة","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q08","type":"recall","phase":"practice","prompt":"ما الفرق بين الأجر والثواب؟","answer":"الأجر ما كان في مقابلة العمل، والثواب تفضيلًا وإحسانًا من الله، ويستعمل كل منهما بمعنى الآخر","explain":"الأجر ما كان في مقابلة العمل، والثواب تفضيلًا وإحسانًا من الله، ويستعمل كل منهما بمعنى الآخر","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q09","type":"recall","phase":"practice","prompt":"من هو الطالب في الفن؟","answer":"من شرع في الفن ولم يستقل بتصوير المسائل ولم يقدر على إقامة الأدلة","explain":"من شرع في الفن ولم يستقل بتصوير المسائل ولم يقدر على إقامة الأدلة","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q10","type":"recall","phase":"practice","prompt":"من هو المريد؟","answer":"الطالب المتقدم","explain":"الطالب المتقدم","section":"tj3-quiz","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q12","type":"mcq","phase":"practice","prompt":"لماذا ابتدأ الناظم نظمه بالبسملة والحمدلة؟","answer":"اقتداءً بالكتاب العزيز الذي بدأت به سورة الفاتحة، وتبعًا للسنة النبوية في حديث «كل أمر ذي بال لا يبدأ فيه ببسم الله الرحمن الرحيم فهو أقطع بركة».","explain":"أراد الناظم أن يكون نظمه مباركًا فاتحة باسم الله والحمد لله، كما أمر النبي ﷺ في حديثه أن كل أمر ذي بال لا يبدأ فيه ببسم الله الرحمن الرحيم فهو أقطع بركة.","section":"tj3-basmala","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q13","type":"cloze","phase":"practice","prompt":"الطالب في الفن هو من __________ فيه ولم يستقل بتصوير المسائل ولم يقدر على إقامة الأدلة.","answer":"شرع","explain":"الطالب هو من شرع في الفن دون أن يستقل بتصوير المسائل أو يقيم الأدلة. أما المريد فهو الطالب المتقدم الذي تجاوز هذه المرحلة.","section":"tj3-terms","difficulty":3},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"sr1-q01","type":"recall","phase":"pretest","prompt":"ما تعريف السيرة النبوية؟","answer":"كل ما يتصل بحياة النبي ﷺ منذ مولده حتى وفاته","explain":"كل ما يتصل بحياة النبي ﷺ منذ مولده حتى وفاته","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q02","type":"recall","phase":"pretest","prompt":"ما الفرق بين السيرة والمغازي؟","answer":"السيرة تشمل كل حياة النبي ﷺ، والمغازي مختصة بأخبار الغزو والصرايا والبعوث بعد الهجرة","explain":"السيرة تشمل كل حياة النبي ﷺ، والمغازي مختصة بأخبار الغزو والصرايا والبعوث بعد الهجرة","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q03","type":"recall","phase":"practice","prompt":"من هو مؤلف السيرة النبوية المشهورة؟","answer":"أبو محمد عبد الملك بن هشام المعافري (ت 218هـ)","explain":"أبو محمد عبد الملك بن هشام المعافري (ت 218هـ)","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q04","type":"recall","phase":"practice","prompt":"من هو الذي شرح كتاب ابن هشام؟","answer":"أبو القاسم عبد الرحمن السهيلي الأندلسي (ت 581هـ) في الروض الأنف","explain":"أبو القاسم عبد الرحمن السهيلي الأندلسي (ت 581هـ) في الروض الأنف","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q05","type":"recall","phase":"practice","prompt":"من هو أول من صنف في المغازي؟","answer":"عروة بن الزبير رضي الله عنه","explain":"عروة بن الزبير رضي الله عنه","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q06","type":"recall","phase":"practice","prompt":"من هو أول من دوّن المغازي بترتيب واضح؟","answer":"ابن شهاب الزهري","explain":"ابن شهاب الزهري","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q07","type":"recall","phase":"practice","prompt":"من هو أول من ألف مفرداً وأخرجه للناس في المغازي؟","answer":"موسى بن عقبة","explain":"موسى بن عقبة","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q08","type":"recall","phase":"practice","prompt":"إلى من ينتهي النسب الشريف باتفاق الأمة؟","answer":"عدنان","explain":"عدنان","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q09","type":"recall","phase":"practice","prompt":"من هو أول من جمع قريش وسكنها مكة؟","answer":"قصي بن كلاب","explain":"قصي بن كلاب","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q10","type":"recall","phase":"practice","prompt":"كم اسماً للنبي ﷺ ذكر الجزولي في دلائل الخيرات؟","answer":"200 اسم","explain":"200 اسم","section":"h1-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q12","type":"mcq","phase":"practice","prompt":"إذا أردت دراسة أخبار الغزوات التي وقعت بعد الهجرة، فأي علم من العلوم التالية أحتاجه؟","answer":"المغازي","explain":"المغازي مختصة بأخبار الغزو والصرايا والبعوث بعد الهجرة، بينما السيرة تشمل كل حياة النبي ﷺ منذ مولده حتى وفاته","section":"h1-def","difficulty":2},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q13","type":"cloze","phase":"practice","prompt":"النسب الشريف للنبي ﷺ ينتهي باتفاق الأمة إلى ______.","answer":"عدنان","explain":"إليه إجماع الأمة في النسب، وما بعده مختلف فيه","section":"h1-lineage","difficulty":3},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr2-q01","type":"recall","phase":"pretest","prompt":"متى مات عبد الله بن عبد المطلب؟","answer":"قبل مولد النبي ﷺ، وكان جنينًا في بطن أمه","explain":"قبل مولد النبي ﷺ، وكان جنينًا في بطن أمه","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q02","type":"recall","phase":"pretest","prompt":"كم كان عمر عبد الله عند وفاته؟","answer":"25 سنة","explain":"25 سنة","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q03","type":"recall","phase":"practice","prompt":"أين توفي عبد الله؟","answer":"بالمدينة، في دار النابغة من بني عدي بن النجار","explain":"بالمدينة، في دار النابغة من بني عدي بن النجار","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q04","type":"recall","phase":"practice","prompt":"من هي أمة بنت وهب؟","answer":"أم النبي ﷺ، بنت وهب بن عبد مناف","explain":"أم النبي ﷺ، بنت وهب بن عبد مناف","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q05","type":"recall","phase":"practice","prompt":"أين تربّت أمة بنت وهب؟","answer":"في بيت عمها وهيب بن عبد مناف","explain":"في بيت عمها وهيب بن عبد مناف","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q06","type":"recall","phase":"practice","prompt":"كم كان عمر النبي ﷺ عندما زار قبر أبيه؟","answer":"6 سنوات","explain":"6 سنوات","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q07","type":"recall","phase":"practice","prompt":"أين توفيت أمة بنت وهب؟","answer":"بالأبواء، بين مكة والمدينة","explain":"بالأبواء، بين مكة والمدينة","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q08","type":"recall","phase":"practice","prompt":"من الذي حفر قبر أم النبي ﷺ؟","answer":"النبي ﷺ نفسه بيديه الصغيرتين، مع أم أيمن","explain":"النبي ﷺ نفسه بيديه الصغيرتين، مع أم أيمن","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q09","type":"recall","phase":"practice","prompt":"من الذي كفله بعد وفاة أمه؟","answer":"جده عبد المطلب بن هاشم","explain":"جده عبد المطلب بن هاشم","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q10","type":"recall","phase":"practice","prompt":"ما حديث الابتلاء؟","answer":"«أي الناس أشد بلاء؟ الأنبياء ثم الصالحون ثم الأمثل فالأمثل»","explain":"«أي الناس أشد بلاء؟ الأنبياء ثم الصالحون ثم الأمثل فالأمثل»","section":"s2-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q12","type":"mcq","phase":"practice","prompt":"ما أول ما فعله عبد المطلب عندما علم بوفاة أمة؟","answer":"فضمه وقال له: أنت ابني، أنت ابني","explain":"بعد أن وصل النبي ﷺ إلى بيت عبد المطلب وبكى قائلاً ماتت أمي، فضمه عبد المطلب وقال له أنت ابني","section":"s2-death","difficulty":2},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q13","type":"cloze","phase":"practice","prompt":"توفي عبد الله بن عبد المطلب وعمره ______ سنة.","answer":"25","explain":"عمره عند الوفاة 25 سنة","section":"s2-father","difficulty":3},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr3-q01","type":"recall","phase":"pretest","prompt":"من الذي أعاد حفر زمزم؟","answer":"عبد المطلب بن هاشم","explain":"عبد المطلب بن هاشم","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q02","type":"recall","phase":"pretest","prompt":"منذ متى لم تنضب زمزم؟","answer":"منذ 4000 سنة","explain":"منذ 4000 سنة","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q03","type":"recall","phase":"practice","prompt":"ما نذر عبد المطلب؟","answer":"إن رزق الله له عشرة نفر ثم بلغوا معه حتى يمنعوه، ليذبحن أحدهم لله عند الكعبة","explain":"إن رزق الله له عشرة نفر ثم بلغوا معه حتى يمنعوه، ليذبحن أحدهم لله عند الكعبة","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q04","type":"recall","phase":"practice","prompt":"على من خرج القدح في الاستقسام؟","answer":"على عبد الله، أصغر أبناء عبد المطلب وأحبها إليه","explain":"على عبد الله، أصغر أبناء عبد المطلب وأحبها إليه","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q05","type":"recall","phase":"practice","prompt":"كم بلغت الإبل في الفداء؟","answer":"100 بعير","explain":"100 بعير","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q06","type":"recall","phase":"practice","prompt":"لماذا يقول النبي ﷺ «أنا ابن الذبيحين»؟","answer":"لأن إسماعيل عليه السلام وعبد الله بن عبد المطلب كلاهما فُدي بذبح","explain":"لأن إسماعيل عليه السلام وعبد الله بن عبد المطلب كلاهما فُدي بذبح","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q07","type":"recall","phase":"practice","prompt":"من هو هاشم بن عبد مناف؟","answer":"جد النبي ﷺ، سيد قريش، أول من أطعم الثريد بمكة","explain":"جد النبي ﷺ، سيد قريش، أول من أطعم الثريد بمكة","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q08","type":"recall","phase":"practice","prompt":"ما هما الرحلتان اللتان سنّهما هاشم؟","answer":"رحلة الشتاء إلى اليمن ورحلة الصيف إلى الشام","explain":"رحلة الشتاء إلى اليمن ورحلة الصيف إلى الشام","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q09","type":"recall","phase":"practice","prompt":"ما الإيلاف؟","answer":"اتفاقية تجارية وأمان بين القبائل والدول، فتح أسواق الشام واليمن والحبشة أمام تجار مكة","explain":"اتفاقية تجارية وأمان بين القبائل والدول، فتح أسواق الشام واليمن والحبشة أمام تجار مكة","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q10","type":"recall","phase":"practice","prompt":"ما سورة قريش؟","answer":"«لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ۝ فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ ۝ الَّذِي أَطْعَمَهُم مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ»","explain":"«لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ۝ فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ ۝ الَّذِي أَطْعَمَهُم مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ»","section":"s3-quiz","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q12","type":"mcq","phase":"practice","prompt":"ما الذي منع عبد المطلب من ذبح ابنه عبد الله مباشرة؟","answer":"قريش منعته وأشاروا عليه باستشارة عرافة","explain":"قامت إليه قريش من أنديتها فمنعته، وأشاروا عليه أن يذهب إلى الحجاز فإن بها عرافة","section":"s3-nadhr","difficulty":2},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q13","type":"cloze","phase":"practice","prompt":"الإيلاف: اتفاقية تجارية وأمان بين ______ و______.","answer":"القبائل والدول","explain":"الإيلاف اتفاقية أو عهد بين فريقين، جمع بينهما بعد تفرق","section":"s3-ilaf","difficulty":3},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"hd1-q01","type":"recall","phase":"pretest","prompt":"ما اسم الكتاب الذي سندرسه؟","answer":"الأربعين النووية","explain":"الأربعين النووية","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q02","type":"recall","phase":"pretest","prompt":"من هو مؤلف الأربعين النووية؟","answer":"الإمام محي الدين شرف النووي","explain":"الإمام محي الدين شرف النووي","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q03","type":"recall","phase":"practice","prompt":"كم حديثًا في الأربعين النووية؟","answer":"40 حديثًا","explain":"40 حديثًا","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q04","type":"recall","phase":"practice","prompt":"ما حديث طلب العلم الذي رواه مسلم؟","answer":"«من سلك طريقًا يلتمس به علمًا سهّل الله له به طريقًا إلى الجنة»","explain":"«من سلك طريقًا يلتمس به علمًا سهّل الله له به طريقًا إلى الجنة»","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q05","type":"recall","phase":"practice","prompt":"ما حديث «من يرد الله به خيرًا»؟","answer":"«من يرد الله به خيرًا يفقهه في الدين» — متفق عليه","explain":"«من يرد الله به خيرًا يفقهه في الدين» — متفق عليه","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q06","type":"recall","phase":"practice","prompt":"ما المحجة البيضاء؟","answer":"جادة الطريق، طريق النبي ﷺ وأصحابه وسلف الأمة","explain":"جادة الطريق، طريق النبي ﷺ وأصحابه وسلف الأمة","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q07","type":"recall","phase":"practice","prompt":"ما فضل الصلاة على النبي ﷺ في هذا العلم؟","answer":"يتصل إسنادك بالنبي ﷺ، وتحيي سنة قراءة الحديث بالسند المتصل، وتنال النظارة","explain":"يتصل إسنادك بالنبي ﷺ، وتحيي سنة قراءة الحديث بالسند المتصل، وتنال النظارة","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q08","type":"recall","phase":"practice","prompt":"ما حديث النظارة الذي رواه ابن ماجه؟","answer":"«نظر الله امرئ سمع مقاله فبلغها، فرب حامل فقه غير فقيه، ورب حامل فقه إلى من هو أفقه منه»","explain":"«نظر الله امرئ سمع مقاله فبلغها، فرب حامل فقه غير فقيه، ورب حامل فقه إلى من هو أفقه منه»","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q09","type":"recall","phase":"practice","prompt":"ما شروط الأربعين النووية؟","answer":"أكثرها صحيحة، معظمها في البخاري ومسلم، محذوفة الأسانيد ليسهل حفظها","explain":"أكثرها صحيحة، معظمها في البخاري ومسلم، محذوفة الأسانيد ليسهل حفظها","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q10","type":"recall","phase":"practice","prompt":"ما الشرح المعتمد للأربعين النووية؟","answer":"شرح الأربعين النووية لابن دقيق العيد","explain":"شرح الأربعين النووية لابن دقيق العيد","section":"hd1-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q12","type":"mcq","phase":"practice","prompt":"ما هي شروط الأربعين النووية التي ذكرها الدرس؟","answer":"أكثرها صحيحة، معظمها في البخاري ومسلم، محذوفة الأسانيد ليسهل حفظها","explain":"ذكر الدرس في فقرة المنهج أن النووي اشترط في أحاديث الأربعين أن تكون أكثرها صحيحة، وأن معظمها في البخاري ومسلم، وأنها محذوفة الأسانيد ليسهل حفظها.","section":"hd1-method","difficulty":2},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q13","type":"cloze","phase":"practice","prompt":"ما المقصود بالمحجة البيضاء في حديث النبي ﷺ؟","answer":"جادة الطريق، طريق النبي ﷺ وأصحابه وسلف الأمة","explain":"أوضح الدرس أن المحجة البيضاء هي جادة الطريق، أي طريق النبي ﷺ وأصحابه وسلف الأمة، وأن معنى «ليلها كنهارها» هو أنها واضحة لا لبس فيها.","section":"hd1-path","difficulty":3},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd2-q01","type":"recall","phase":"pretest","prompt":"ما أول حديث في الأربعين النووية؟","answer":"«إنما الأعمال بالنيات»","explain":"«إنما الأعمال بالنيات»","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q02","type":"recall","phase":"pretest","prompt":"من رواه هذا الحديث؟","answer":"البخاري ومسلم عن عمر بن الخطاب","explain":"البخاري ومسلم عن عمر بن الخطاب","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q03","type":"recall","phase":"practice","prompt":"ما معنى «إنما»؟","answer":"تفيد الحصر","explain":"تفيد الحصر","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q04","type":"recall","phase":"practice","prompt":"ما النية شرعًا؟","answer":"اعتقاد القلب فعل الشيء وعزمه عليه من غير تردد","explain":"اعتقاد القلب فعل الشيء وعزمه عليه من غير تردد","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q05","type":"recall","phase":"practice","prompt":"ما المرتبة الأولى من مراتب النية؟","answer":"تمييز العادات عن العبادات","explain":"تمييز العادات عن العبادات","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q06","type":"recall","phase":"practice","prompt":"ما المرتبة الثانية من مراتب النية؟","answer":"تمييز العبادات بعضها ببعض","explain":"تمييز العبادات بعضها ببعض","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q07","type":"recall","phase":"practice","prompt":"ما المرتبة الثالثة من مراتب النية؟","answer":"الإخلاص","explain":"الإخلاص","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q08","type":"recall","phase":"practice","prompt":"ما الإخلاص؟","answer":"أن يقصد العبد بعمله وجه الله ولا يريد غيره","explain":"أن يقصد العبد بعمله وجه الله ولا يريد غيره","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q09","type":"recall","phase":"practice","prompt":"ما سبب ورود حديث النية؟","answer":"رجل هاجر من مكة إلى المدينة ليتزوج امرأة يقال لها أم قيس","explain":"رجل هاجر من مكة إلى المدينة ليتزوج امرأة يقال لها أم قيس","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q10","type":"recall","phase":"practice","prompt":"ما هي أصول الإسلام الثلاث؟","answer":"حديث عمر «إنما الأعمال بالنيات»، حديث عائشة «من أحدث في أمرنا هذا ما ليس منه فهو رد»، حديث النعمان بن بشير «الحلال بين والحرام بين»","explain":"حديث عمر «إنما الأعمال بالنيات»، حديث عائشة «من أحدث في أمرنا هذا ما ليس منه فهو رد»، حديث النعمان بن بشير «الحلال بين والحرام بين»","section":"hd2-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q12","type":"mcq","phase":"practice","prompt":"ما المرتبة الأولى من مراتب النية كما ذكرها الدرس؟","answer":"تمييز العادات عن العبادات","explain":"أوضح الدرس أن المرتبة الأولى من مراتب النية هي تمييز العادات عن العبادات، فالاستحمام عادة لكن بالنية يصبح عبادة.","section":"hd2-ranks","difficulty":2},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q13","type":"cloze","phase":"practice","prompt":"ما معنى النية شرعًا كما ورد في الدرس؟","answer":"اعتقاد القلب فعل الشيء وعزمه عليه من غير تردد","explain":"عرّف الدرس النية في الشرع بأنها اعتقاد القلب فعل الشيء وعزمه عليه من غير تردد، ولا يشترط التردد وإن تردد فلا بأس.","section":"hd2-meaning","difficulty":3},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd3-q01","type":"recall","phase":"pretest","prompt":"ما اسم الحديث الثاني في الأربعين النووية؟","answer":"حديث جبريل","explain":"حديث جبريل","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q02","type":"recall","phase":"pretest","prompt":"من رواه وعن من؟","answer":"رواه مسلم عن عمر بن الخطاب رضي الله عنه","explain":"رواه مسلم عن عمر بن الخطاب رضي الله عنه","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q03","type":"recall","phase":"practice","prompt":"ما مراتب الدين الثلاث؟","answer":"الإسلام والإيمان والإحسان — الثلاثة كلها دين","explain":"الإسلام والإيمان والإحسان — الثلاثة كلها دين","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q04","type":"recall","phase":"practice","prompt":"كم أركان الإسلام؟ وما هي؟","answer":"خمس: الشهادتان، الصلاة، الزكاة، الصيام، الحج","explain":"خمس: الشهادتان، الصلاة، الزكاة، الصيام، الحج","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q05","type":"recall","phase":"practice","prompt":"ما الأصناف الثمانية للزكاة؟","answer":"الفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل","explain":"الفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q06","type":"recall","phase":"practice","prompt":"ما الصيام في اللغة وفي الشرع؟","answer":"في اللغة: الإمساك والكف عن الشيء — وفي شريعتنا: الإمساك عن الطعام والشراب وشهوتي البطن والفرج","explain":"في اللغة: الإمساك والكف عن الشيء — وفي شريعتنا: الإمساك عن الطعام والشراب وشهوتي البطن والفرج","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q07","type":"recall","phase":"practice","prompt":"ما قصة زينب امرأة أحمس؟","answer":"حجّت مصمتة (صامتة لا تتكلم)، فقال لها أبو بكر: تكلمي فإن هذا لا يحل، هذا من عمل الجاهلية — والصيام عن الكلام كان في شريعة الأمم السابقة","explain":"حجّت مصمتة (صامتة لا تتكلم)، فقال لها أبو بكر: تكلمي فإن هذا لا يحل، هذا من عمل الجاهلية — والصيام عن الكلام كان في شريعة الأمم السابقة","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q08","type":"recall","phase":"practice","prompt":"ما أركان الحج الأربعة؟","answer":"الإحرام، الطواف، السعي، الوقوف بعرفة","explain":"الإحرام، الطواف، السعي، الوقوف بعرفة","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q09","type":"recall","phase":"practice","prompt":"كم أركان الإيمان؟ وما هي؟","answer":"ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره","explain":"ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q10","type":"recall","phase":"practice","prompt":"ما الإحسان؟","answer":"أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك — وهذه هي المراقبة","explain":"أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك — وهذه هي المراقبة","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q11","type":"recall","phase":"practice","prompt":"ما أشراط الساعة الكبرى؟","answer":"نزول عيسى بن مريم، والدجال، ويأجوج ومأجوج، وطلوع الشمس من مغربها","explain":"نزول عيسى بن مريم، والدجال، ويأجوج ومأجوج، وطلوع الشمس من مغربها","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q12","type":"recall","phase":"practice","prompt":"ما أشراط الساعة المذكورة في الحديث؟","answer":"أن تلد الأم ربتها، وأن ترى الحفاة العراة العالة رعاء الشاء يتطاولون في البنيان","explain":"أن تلد الأم ربتها، وأن ترى الحفاة العراة العالة رعاء الشاء يتطاولون في البنيان","section":"hd3-quiz","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"ak1-q01","type":"recall","phase":"pretest","prompt":"ما اسم الكتاب المقرر في مادة الأخلاق؟","answer":"تذكرة السامع والمتكلم في أدب العالم والمتعلم.","explain":"تذكرة السامع والمتكلم في أدب العالم والمتعلم.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q02","type":"recall","phase":"pretest","prompt":"من مؤلف الكتاب كما ورد في الدرس؟","answer":"الإمام بدر الدين ابن جماعة الكناني الشافعي.","explain":"الإمام بدر الدين ابن جماعة الكناني الشافعي.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q03","type":"recall","phase":"practice","prompt":"من مدرّس المادة؟","answer":"الأستاذ محمد جمعة عياد.","explain":"الأستاذ محمد جمعة عياد.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q04","type":"recall","phase":"practice","prompt":"ما موضوع الكتاب؟","answer":"جملة من آداب العالم والمتعلم وأخلاقهما.","explain":"جملة من آداب العالم والمتعلم وأخلاقهما.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q05","type":"recall","phase":"practice","prompt":"كيف تُكتسب الأخلاق بحسب الأستاذ؟","answer":"بكثرة مصاحبة ومرافقة أهل الأدب والأخلاق من العلماء والمشايخ.","explain":"بكثرة مصاحبة ومرافقة أهل الأدب والأخلاق من العلماء والمشايخ.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q06","type":"recall","phase":"practice","prompt":"لماذا كان الفعل أبلغ من القول والقراءة؟","answer":"لأن الأخلاق تظهر في السلوك العملي والقدوة.","explain":"لأن الأخلاق تظهر في السلوك العملي والقدوة.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q07","type":"recall","phase":"practice","prompt":"ما غاية دراسة هذه المادة مع العلوم الشرعية؟","answer":"اكتساب أخلاق النبي ﷺ والتأدب مع تحصيل العلم.","explain":"اكتساب أخلاق النبي ﷺ والتأدب مع تحصيل العلم.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q08","type":"recall","phase":"practice","prompt":"ما صورة العالم الذي دعا الأستاذ إلى أن نكون منه؟","answer":"العالم العامل بعلمه والمتأدب بأخلاقه.","explain":"العالم العامل بعلمه والمتأدب بأخلاقه.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q09","type":"recall","phase":"practice","prompt":"ما المرحلة الجامعية التي ذكر الأستاذ أنه تخرج منها بالأزهر؟","answer":"كلية الدراسات الإسلامية والعربية بجامعة الأزهر.","explain":"كلية الدراسات الإسلامية والعربية بجامعة الأزهر.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q10","type":"recall","phase":"practice","prompt":"ما التخصص الذي ذكره الأستاذ في دراساته العليا؟","answer":"ماجستير في الشريعة والقانون بالمعهد العالي لأصول الدين بجامعة الزيتونة.","explain":"ماجستير في الشريعة والقانون بالمعهد العالي لأصول الدين بجامعة الزيتونة.","section":"ak1-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q12","type":"mcq","phase":"practice","prompt":"كيف تُكتسب الأخلاق بحسب ما ذكره الأستاذ في الدرس؟","answer":"بكثرة مصاحبة ومرافقة أهل الأدب والأخلاق من العلماء والمشايخ.","explain":"لأن الأخلاق تُتعلَّم بالقدوة العملية والمصاحبة، لا بالقراءة وحدها.","section":"ak1-adab","difficulty":2},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q13","type":"cloze","phase":"practice","prompt":"أكمل الفراغ: غاية طلب العلم هي الجمع بين .............. والتأدب بأخلاق النبي ﷺ.","answer":"العلم الشرعي","explain":"لأن طالب العلم يجمع بين تحصيل العلم الشرعي والتخلق بأخلاق النبي ﷺ والعمل بالعلم.","section":"ak1-summary","difficulty":2},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak2-q01","type":"recall","phase":"pretest","prompt":"ما عنوان كتاب ابن جماعة الذي يدرسه المقرر؟","answer":"تذكرة السامع والمتكلم في أدب العالم والمتعلم.","explain":"تذكرة السامع والمتكلم في أدب العالم والمتعلم.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q02","type":"recall","phase":"pretest","prompt":"ما معنى براعة الاستهلال؟","answer":"أن يذكر المؤلف في مطلع كتابه ما ينبئ عن مقصوده.","explain":"أن يذكر المؤلف في مطلع كتابه ما ينبئ عن مقصوده.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q03","type":"recall","phase":"practice","prompt":"ما الحاجة التي ذكرها المؤلف سببًا لتصنيف المختصر؟","answer":"حاجة الطلبة إلى معرفة آداب العالم والمتعلم، مع ما قد يمنعهم من السؤال أو ينفّرهم.","explain":"حاجة الطلبة إلى معرفة آداب العالم والمتعلم، مع ما قد يمنعهم من السؤال أو ينفّرهم.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q04","type":"recall","phase":"practice","prompt":"من أين جمع المؤلف مادة كتابه؟","answer":"مما سمعه، وأخذه عن المشايخ، وقرأه في المطالعات، واستفاده في المذاكرات.","explain":"مما سمعه، وأخذه عن المشايخ، وقرأه في المطالعات، واستفاده في المذاكرات.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q05","type":"recall","phase":"practice","prompt":"لماذا حذف المؤلف الأسانيد والأدلة المطولة؟","answer":"كيلا يطول الكتاب على المطالع أو يمله.","explain":"كيلا يطول الكتاب على المطالع أو يمله.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q06","type":"recall","phase":"practice","prompt":"كم بابًا في الكتاب؟ اذكر موضوعاتها إجمالًا.","answer":"خمسة: فضل العلم، وآداب العالم، وآداب المتعلم، وآداب صحبة الكتب، وآداب سكن المدارس.","explain":"خمسة: فضل العلم، وآداب العالم، وآداب المتعلم، وآداب صحبة الكتب، وآداب سكن المدارس.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q07","type":"recall","phase":"practice","prompt":"ما موضوع الباب الأول؟","answer":"فضل العلم والعلماء وفضل تعليمه وتعلمه.","explain":"فضل العلم والعلماء وفضل تعليمه وتعلمه.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q08","type":"recall","phase":"practice","prompt":"بماذا فسّر الأستاذ التفقه في حديث «من يرد الله به خيرًا»؟","answer":"بالتوفيق إلى طلب العلم ومجالسة العلماء والتعلم في الدين.","explain":"بالتوفيق إلى طلب العلم ومجالسة العلماء والتعلم في الدين.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q09","type":"recall","phase":"practice","prompt":"ما الوصف الذي ذكره الدرس للعلماء في حديث مشهور؟","answer":"أنهم ورثة الأنبياء.","explain":"أنهم ورثة الأنبياء.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q10","type":"recall","phase":"practice","prompt":"ما بعض المعاني التي ذكرها الأستاذ لوضع الملائكة أجنحتها لطالب العلم؟","answer":"التواضع لطالب العلم، أو حضور مجلسه، أو توقيره، أو إعانته على بلوغ مقصده.","explain":"التواضع لطالب العلم، أو حضور مجلسه، أو توقيره، أو إعانته على بلوغ مقصده.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q11","type":"recall","phase":"practice","prompt":"ما الصلة التي أبرزها الدرس بين العلم والأخلاق؟","answer":"أن أهل العلم قدوة، وأن العلم ينبغي أن يقترن بالأدب والعمل والخشية.","explain":"أن أهل العلم قدوة، وأن العلم ينبغي أن يقترن بالأدب والعمل والخشية.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q12","type":"recall","phase":"practice","prompt":"ما الأثر المنقول عن ملازمة ابن القاسم للإمام مالك؟","answer":"ذكر أنه صحبه عشرين سنة، تعلّم الأدب في معظمها والعلم في سنتين، بحسب ما أورده الأستاذ.","explain":"ذكر أنه صحبه عشرين سنة، تعلّم الأدب في معظمها والعلم في سنتين، بحسب ما أورده الأستاذ.","section":"ak2-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak3-q01","type":"recall","phase":"pretest","prompt":"من العلماء الذين تشملهم فضائل العلم بحسب افتتاح الفصل؟","answer":"العلماء العاملون الأبرار المتقون الذين يقصدون وجه الله.","explain":"العلماء العاملون الأبرار المتقون الذين يقصدون وجه الله.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q02","type":"recall","phase":"pretest","prompt":"ما النيات التي حذّر الدرس منها في طلب العلم؟","answer":"المراء، ومكاثرة العلماء، وجذب أنظار الناس، وطلب الجاه أو المال أو الشهرة.","explain":"المراء، ومكاثرة العلماء، وجذب أنظار الناس، وطلب الجاه أو المال أو الشهرة.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q03","type":"recall","phase":"practice","prompt":"ما النية التي دعا الأستاذ إلى تجديدها؟","answer":"طلب العلم ابتغاء مرضاة الله ورفع الجهل عن النفس.","explain":"طلب العلم ابتغاء مرضاة الله ورفع الجهل عن النفس.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q04","type":"recall","phase":"practice","prompt":"ما أول أدب ذكره المؤلف للعالم في نفسه؟","answer":"دوام مراقبة الله تعالى في السر والعلانية.","explain":"دوام مراقبة الله تعالى في السر والعلانية.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q05","type":"recall","phase":"practice","prompt":"متى يجوز للعالم الذهاب إلى المتعلم بدل مجيء المتعلم إليه؟","answer":"عند ضرورة أو حاجة أو مصلحة دينية راجحة، مع حسن النية وانتفاء مفسدة إذلال العلم.","explain":"عند ضرورة أو حاجة أو مصلحة دينية راجحة، مع حسن النية وانتفاء مفسدة إذلال العلم.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q06","type":"recall","phase":"practice","prompt":"ما معنى الزهد في الدنيا كما شرحه الأستاذ؟","answer":"زهد القلب وعدم تعلقه بالدنيا، لا لزوم مظهر الفقر أو ترك المباحات.","explain":"زهد القلب وعدم تعلقه بالدنيا، لا لزوم مظهر الفقر أو ترك المباحات.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q07","type":"recall","phase":"practice","prompt":"ما الأغراض التي لا ينبغي أن يجعل العلم وسيلة إليها؟","answer":"الجاه والمال والسمعة والشهرة والخدمة والتقدم على الأقران.","explain":"الجاه والمال والسمعة والشهرة والخدمة والتقدم على الأقران.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q08","type":"recall","phase":"practice","prompt":"ما المقصود باجتناب مواضع التهمة؟","answer":"الابتعاد عما يوقع الناس في سوء الظن أو يقدح في المروءة، ولو كان الفعل جائزًا في أصله.","explain":"الابتعاد عما يوقع الناس في سوء الظن أو يقدح في المروءة، ولو كان الفعل جائزًا في أصله.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q09","type":"recall","phase":"practice","prompt":"ما الشعائر التي يحافظ عليها العالم؟","answer":"شعائر الإسلام وظواهر أحكامه، بامتثال المأمورات واجتناب المنهيات.","explain":"شعائر الإسلام وظواهر أحكامه، بامتثال المأمورات واجتناب المنهيات.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q10","type":"recall","phase":"practice","prompt":"ما أمثلة المندوبات التي ذكرها الأستاذ؟","answer":"قيام الليل، وقراءة القرآن، والذكر، والتذكير، والصدقة.","explain":"قيام الليل، وقراءة القرآن، والذكر، والتذكير، والصدقة.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q11","type":"recall","phase":"practice","prompt":"لماذا يحافظ العالم على النوافل بحسب الدرس؟","answer":"ليكون قدوة وأسوة للناس في العبادة والسلوك.","explain":"ليكون قدوة وأسوة للناس في العبادة والسلوك.","section":"ak3-quiz","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q13","type":"mcq","phase":"practice","prompt":"كم عدد آداب العالم في نفسه التي ذكرها الدرس؟","answer":"سبع آداب.","explain":"ذكر الدرس سبعًا من آداب العالم في نفسه: مراقبة الله، وصيانة العلم، والزهد القلبي، وإخلاص القصد، ونزاهة المكاسب، وصيانة المروءة، والمحافظة على شعائر الإسلام والمندوبات.","section":"ak3-conduct","difficulty":2},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"nh1-q01","type":"recall","phase":"pretest","prompt":"ما الكتاب الذي اختاره الأستاذ للمادة؟","answer":"كتاب «الدروس النحوية»، والدرس يخص الجزء الثاني منه.","explain":"كتاب «الدروس النحوية»، والدرس يخص الجزء الثاني منه.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q02","type":"recall","phase":"pretest","prompt":"كيف وصف الأستاذ الكتاب؟","answer":"وصفه بأنه شيق ومبسط، ويحوي معلومات قيمة وضرورية للمبتدئ.","explain":"وصفه بأنه شيق ومبسط، ويحوي معلومات قيمة وضرورية للمبتدئ.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q03","type":"recall","phase":"practice","prompt":"كيف قُسم تدريس الجزء الثاني من الكتاب؟","answer":"إلى جزأين: الأول في السداسي الأول والثاني في السداسي الثاني.","explain":"إلى جزأين: الأول في السداسي الأول والثاني في السداسي الثاني.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q04","type":"recall","phase":"practice","prompt":"ما أقسام الكلام التي ذكرها في خطة المقرر؟","answer":"الاسم والفعل والحرف.","explain":"الاسم والفعل والحرف.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q05","type":"recall","phase":"practice","prompt":"بأي اعتبار يقسم الدرس الأفعال أولًا؟","answer":"بحسب الزمن إلى ماضٍ وحاضر أو مستقبل.","explain":"بحسب الزمن إلى ماضٍ وحاضر أو مستقبل.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q06","type":"recall","phase":"practice","prompt":"ما التقسيم الآخر للأفعال الذي ذكره؟","answer":"صحيحة الآخر ومعتلة الآخر، ثم معربة ومبنية.","explain":"صحيحة الآخر ومعتلة الآخر، ثم معربة ومبنية.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q07","type":"recall","phase":"practice","prompt":"ما العوامل التي ستدرس في باب الأفعال؟","answer":"عوامل الرفع والنصب والجزم، وذكر الأستاذ أن الرفع يكون لعدم وجود ناصب أو جازم.","explain":"عوامل الرفع والنصب والجزم، وذكر الأستاذ أن الرفع يكون لعدم وجود ناصب أو جازم.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q08","type":"recall","phase":"practice","prompt":"اذكر ثلاثة من تقسيمات الأسماء المعلنة.","answer":"مثل: صحيحة الآخر ومعتلة الآخر، نكرة ومعرفة، مفرد ومثنى وجمع، مذكر ومؤنث، منون وغير منون.","explain":"مثل: صحيحة الآخر ومعتلة الآخر، نكرة ومعرفة، مفرد ومثنى وجمع، مذكر ومؤنث، منون وغير منون.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q09","type":"recall","phase":"practice","prompt":"لماذا تُعد العربية والنحو من علوم الآلة؟","answer":"لأنها وسائل لفهم كلام الله وكلام النبي ﷺ.","explain":"لأنها وسائل لفهم كلام الله وكلام النبي ﷺ.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q10","type":"recall","phase":"practice","prompt":"ما الغاية من وضع قواعد النحو بحسب عرض الأستاذ؟","answer":"حفظ العربية من اللحن والتحريف والاندثار، وإعانة المتعلم على فهم النصوص.","explain":"حفظ العربية من اللحن والتحريف والاندثار، وإعانة المتعلم على فهم النصوص.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q11","type":"recall","phase":"practice","prompt":"من الذي ذكره الأستاذ في سياق وضع قواعد النحو؟","answer":"ذكر عليًا رضي الله عنه وأبا الأسود الدؤلي.","explain":"ذكر عليًا رضي الله عنه وأبا الأسود الدؤلي.","section":"nh1-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q13","type":"mcq","phase":"practice","prompt":"أي العبارات التالية تلخص غاية علم النحو كما عرضها الأستاذ في الدرس؟","answer":"النحو من علوم الآلة التي تعين على فهم القرآن والحديث وصيانة العربية من اللحن والتحريف والاندثار.","explain":"ذكر الأستاذ أن النحو وسيلة لفهم القرآن الكريم والحديث النبوي، وأنه من علوم الآلة التي يحتاج إليها طالب العلم، وأن غاية وضع قواعده صيانة اللسان من اللحن والتحريف.","section":"nh1-purpose","difficulty":2},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh2-q01","type":"recall","phase":"pretest","prompt":"إلى ماذا يوجّه علم النحو بحثه في الألفاظ؟","answer":"إلى اللفظة بعد تركيبها مع غيرها بما يؤدي إلى فائدة يحسن السكوت عليها.","explain":"إلى اللفظة بعد تركيبها مع غيرها بما يؤدي إلى فائدة يحسن السكوت عليها.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q02","type":"recall","phase":"pretest","prompt":"ما المجال الذي يبحث في اللفظة المفردة ومعناها؟","answer":"علم اللغة والمعاجم، بحسب شرح الأستاذ.","explain":"علم اللغة والمعاجم، بحسب شرح الأستاذ.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q03","type":"recall","phase":"practice","prompt":"ما أقسام الكلمة الثلاثة؟","answer":"الاسم والفعل والحرف.","explain":"الاسم والفعل والحرف.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q04","type":"recall","phase":"practice","prompt":"عرّف الفعل بحسب الدرس.","answer":"ما يدل على معنى مستقل بالفهم، والزمن جزء من دلالته.","explain":"ما يدل على معنى مستقل بالفهم، والزمن جزء من دلالته.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q05","type":"recall","phase":"practice","prompt":"ما معيار الأستاذ للتفريق بين الماضي والحاضر والمستقبل؟","answer":"وقت التكلم: ما قبله ماضٍ، وما يقع فيه حاضر، وما بعده مستقبل.","explain":"وقت التكلم: ما قبله ماضٍ، وما يقع فيه حاضر، وما بعده مستقبل.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q06","type":"recall","phase":"practice","prompt":"ما أمثلة الماضي والمضارع والأمر التي ذكرها؟","answer":"خرج، ويخرج، واخرج.","explain":"خرج، ويخرج، واخرج.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q07","type":"recall","phase":"practice","prompt":"عرّف الاسم كما ورد في الدرس.","answer":"ما يدل على معنى مستقل بالفهم، وليس الزمن جزءًا من دلالته.","explain":"ما يدل على معنى مستقل بالفهم، وليس الزمن جزءًا من دلالته.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q08","type":"recall","phase":"practice","prompt":"ما أمثلة الأسماء التي ساقها الأستاذ؟","answer":"زيد، ومسلم، وكتاب، وقلم.","explain":"زيد، ومسلم، وكتاب، وقلم.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q09","type":"recall","phase":"practice","prompt":"لماذا لا يستقل الحرف بالفهم بحسب الشرح؟","answer":"لأن معناه يحتاج إلى متعلق من اسم أو فعل حتى يتضح.","explain":"لأن معناه يحتاج إلى متعلق من اسم أو فعل حتى يتضح.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q10","type":"recall","phase":"practice","prompt":"كيف يظهر معنى النفي في مثال «لم»؟","answer":"يتعلق بالفعل، مثل: «لم يخرج زيد»، فيتوجه النفي إلى الخروج.","explain":"يتعلق بالفعل، مثل: «لم يخرج زيد»، فيتوجه النفي إلى الخروج.","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q11","type":"recall","phase":"practice","prompt":"ما المثالان اللذان يوضحان تعلق الحرف بالاسم؟","answer":"«بسم الله» و«الكتاب على الطاولة».","explain":"«بسم الله» و«الكتاب على الطاولة».","section":"nh2-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q13","type":"mcq","phase":"practice","prompt":"ما الفرق الذي يذكره الدرس بين دلالة الاسم ودلالة الفعل؟","answer":"الفعل يدل على معنى مستقل بالفهم ويكون الزمن جزءًا من دلالته، أما الاسم فيدل على معنى مستقل من غير أن يكون الزمن جزءًا من معناه.","explain":"يميز الدرس بين القسمين بعلامة الزمن: خرج يدل على حدث وزمنه الماضي، بينما كتاب يدل على معنى مستقل لا يخبر بذاته متى وقع شيء.","section":"nh2-classes","difficulty":2},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh3-q01","type":"recall","phase":"pretest","prompt":"ما الفرق بين حروف المباني وحروف المعاني؟","answer":"حروف المباني تُركّب لتكوين الكلمات، أما حروف المعاني فتدل على معانٍ في الاستعمال، وقد تعمل في غيرها.","explain":"حروف المباني تُركّب لتكوين الكلمات، أما حروف المعاني فتدل على معانٍ في الاستعمال، وقد تعمل في غيرها.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q02","type":"recall","phase":"pretest","prompt":"كم عدد حروف الأبجدية الذي ذكره الأستاذ؟","answer":"ثمانية وعشرون حرفًا.","explain":"ثمانية وعشرون حرفًا.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q03","type":"recall","phase":"practice","prompt":"إلى كم مجموعة رتّب الأستاذ حروف المعاني بحسب تركيبها؟","answer":"إلى خمس مجموعات: أحادية وثنائية وثلاثية ورباعية وخماسية.","explain":"إلى خمس مجموعات: أحادية وثنائية وثلاثية ورباعية وخماسية.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q04","type":"recall","phase":"practice","prompt":"ما معنى الباء في مثال «بسم الله» بحسب الدرس؟","answer":"من معانيها الاستعانة، وتجر ما بعدها في المثال.","explain":"من معانيها الاستعانة، وتجر ما بعدها في المثال.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q05","type":"recall","phase":"practice","prompt":"ما دلالة الواو والتاء في «والله» و«تالله»؟","answer":"القسم.","explain":"القسم.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q06","type":"recall","phase":"practice","prompt":"ما دلالة السين في «سأكتب»؟","answer":"الاستقبال القريب بحسب شرح الأستاذ.","explain":"الاستقبال القريب بحسب شرح الأستاذ.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q07","type":"recall","phase":"practice","prompt":"ما الفرق الذي ذكره الأستاذ بين الفاء وثم في العطف؟","answer":"الفاء للترتيب، وثم للترتيب مع التراخي.","explain":"الفاء للترتيب، وثم للترتيب مع التراخي.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q08","type":"recall","phase":"practice","prompt":"ما دلالة «لم» كما وصفها المحاضر؟","answer":"حرف نفي وجزم وقلب.","explain":"حرف نفي وجزم وقلب.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q09","type":"recall","phase":"practice","prompt":"ما دلالة «ليت» و«لعل» في أمثلة الدرس؟","answer":"ليت للتمني، ولعل للترجي.","explain":"ليت للتمني، ولعل للترجي.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q10","type":"recall","phase":"practice","prompt":"ما المعنيان اللذان ذكرهما الأستاذ لحرف «إلا»؟","answer":"الاستثناء والحصر.","explain":"الاستثناء والحصر.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q11","type":"recall","phase":"practice","prompt":"ما دلالة «لكن» و«إنما»؟","answer":"لكن للاستدراك، وإنما للحصر.","explain":"لكن للاستدراك، وإنما للحصر.","section":"nh3-quiz","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q13","type":"mcq","phase":"practice","prompt":"كيف تفرق بين حروف المباني وحروف المعاني بحسب ما ذكره الأستاذ؟","answer":"حروف المباني تُركّب لتكوين صورة الكلمة ولا يقصد بها معنى مستقل في التركيب، أما حروف المعاني فتضيف معنى عند استعمالها مع غيرها وقد تؤثر في إعراب ما بعدها.","explain":"حروف المباني مثل الكاف والتاء والباء في «كتب» تبني اللفظ، بينما حروف المعاني مثل الباء في «بسم الله» تضيف معنى الاستعانة وتجر ما بعدها، والسين في «سأكتب» تدل على الاستقبال.","section":"nh3-distinction","difficulty":2},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"}];
